"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[7137],{5357(e){e.exports=JSON.parse('{"title":"AI \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0\ub294, \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\uac00 \ub354 \ud544\uc694\ud558\ub2e4.","date":"2025-05-13","coverUrl":"/kudzu-based-bench/assets/notion/7b2765d8fd07f831.png","html":"<h2 data-notion-block-id=\\"1f0e548d-8a8e-8099-b312-e82d1fd573c1\\" id=\\"1f0e548d-8a8e-8099-b312-e82d1fd573c1\\">AI \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0\ub294, \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\uac00 \ub354 \ud544\uc694\ud558\ub2e4.</h2><a href=\\"https://www.epicai.pro/the-future-of-ai-interaction-beyond-just-text-w22ps\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.epicai.pro/the-future-of-ai-interaction-beyond-just-text-w22ps</a><p data-notion-block-id=\\"1f0e548d-8a8e-80dc-8e9e-da2d651f265e\\"><a href=\\"https://youtu.be/djhEgxQf3Kw?si=E0UTGOFKL-ufC2Pp&#x26;t=677\\">React conf\uc758 \uc2dc\uc5f0 \uc601\uc0c1</a>\uc744 \ubcf4\uace0 AI\uc758 \uc751\ub2f5\uc73c\ub85c \ud14d\uc2a4\ud2b8\ub97c \uc81c\uacf5\ud574\uc8fc\uae30 \ubcf4\ub2e4\ub294, \uc0ac\ub78c\ub4e4\uc740 AI\uc758 \uc751\ub2f5\uc5d0 \ub530\ub77c interaction\uc774\ub098 visualization\ub41c UI\ub97c \ubcf4\uc5ec\uc8fc\uae30\ub97c \uc6d0\ud558\ubbc0\ub85c, \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\uac00 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \ub098\uc544\uac08 \uac83\uc774\ub77c\uace0 \ub9d0\ud558\ub294 \uc9e7\uc740 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://x.ant.design/components/overview\\">Ant Design X</a>\uac19\uc774 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \ub610\ud55c AI\uc5d0 \ub9de\uac8c \uc9c4\ud654\ud558\uace0 \uc788\uc73c\ubbc0\ub85c, \ub0b4 \ud504\ub860\ud2b8\uc5d4\ub4dc \uae30\uc220\uacfc AI\uc640 \uc5b4\ub5bb\uac8c \uacb0\ud569\ud560\uc9c0 \uace0\ubbfc\ud574\ubcf4\ub294 \uac83\uc774 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f0e548d-8a8e-8051-a1ae-f9666b95f7a9\\" id=\\"1f0e548d-8a8e-8051-a1ae-f9666b95f7a9\\">\uc65c \ub098\ub294 Next.js\uac00 \uc544\ub2c8\ub77c Astro\ub97c \uc120\ud0dd\ud588\uc744\uae4c?</h2><a href=\\"https://d13z.dev/blog/07-why-kleinanzeigen-picked-astro-over-nextjs/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://d13z.dev/blog/07-why-kleinanzeigen-picked-astro-over-nextjs/</a><p data-notion-block-id=\\"1f0e548d-8a8e-804f-81c8-d8f96313239b\\">Next.js\uc5d0\uc11c Astro\ub85c \ubcc0\uacbd\ud558\uac8c \ub41c \uc774\uc720\ub97c \uc124\uba85\ud558\ub294 \uae00\uc740 \ub9ce\uc9c0\ub9cc(<a href=\\"https://ones-to-watch.ethansup.net/news/post/15ee548d-8a8e-80b5-9d6e-cfa07648afc4#162e548d-8a8e-80c6-8224-f9618dd9926f\\">Next.js\uc5d0\uc11c Astro\ub85c \ubcc0\uacbd\ud558\uae30</a>) \uc790\uc2e0\uc758 \ubaa9\ud45c\ub97c \uc0c1\uc138\ud558\uac8c \uc124\uba85\ud558\uace0, \uc5ec\ub7ec\uac00\uc9c0 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uc7a5\ub2e8\uc810\uc744 \uac19\uc774 \uc124\uba85\ud558\ub294 \uae00\uc740 \ub9ce\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ud68c\uc0ac\uc5d0\uc11c \uc790\uc2e0\uc5d0\uac8c \uc8fc\uc5b4\uc9c4 \uc694\uad6c\uc0ac\ud56d\uc744 \uba85\ud655\ud558\uac8c \ubd84\uc11d\ud558\uace0 \uc5ec\ub7ec\uac00\uc9c0 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uc7a5\ub2e8\uc810\uc744 \uc18c\uac1c\ud558\uace0, Astro \ub610\ud55c \ub2e8\uc810\uc774 \uc788\uc74c\uc5d0\ub3c4 \uc65c \uc120\ud0dd\ud588\ub294\uc9c0\ub97c \uc790\uc138\ud558\uac8c \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f0e548d-8a8e-807c-ab8c-eaca77b8acdc\\" id=\\"1f0e548d-8a8e-807c-ab8c-eaca77b8acdc\\">\uc77c\ubc18\uc801\uc73c\ub85c, Tanstack Query\uc758 \uc124\uc815\uc744 override\ud558\ub294\uac8c \uc88b\ub2e4.</h2><a href=\\"https://www.kxlaa.com/articles/when-you-might-need-to-override-the-defaults-in-tanstack-query\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.kxlaa.com/articles/when-you-might-need-to-override-the-defaults-in-tanstack-query</a><p data-notion-block-id=\\"1f0e548d-8a8e-8015-ba40-d901b012627d\\">Tanstack Query\uc5d0\uc11c QueryClient\ub97c \uc120\uc5b8\ud558\uba74, \uae30\ubcf8 \uc635\uc158 \uac12\uc744 \uc81c\uacf5\ud558\uace0, \uc77c\ubc18\uc801\uc73c\ub85c \uadf8 \uc124\uc815\uc5d0 \ub530\ub77c \uc0ac\uc6a9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc704 \uae00\uc740 \ub9ce\uc740 \uacbd\uc6b0\uc5d0 \uc774\ub97c override\ud558\ub294 \uac83\uc774 \uc88b\uc740 \uc774\uc720\ub97c \uba87\uac00\uc9c0 \uc608\uc2dc\ub97c \uac04\ub2e8\ud558\uac8c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubb3c\ub860 \uc608\uc2dc\ub97c \ud070 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \ucf54\ub4dc\uc5d0\uc11c \ucc3e\ub294 \uac83\uc740 \uc5b4\ub835\uaca0\uc9c0\ub9cc, \uce90\uc2f1 \uc124\uc815\uc744 \uc778\uc9c0\ud558\uace0 \uc0c1\ud669\uc5d0 \ub530\ub77c \uc801\uc808\ud558\uac8c \uc0ac\uc6a9\ud558\ub294 \uac83\uc740 \ud544\uc694\ud574\ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f0e548d-8a8e-80cd-a796-e26727221a1f\\" id=\\"1f0e548d-8a8e-80cd-a796-e26727221a1f\\">Passkey \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://www.troyhunt.com/passkeys-for-normal-people/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.troyhunt.com/passkeys-for-normal-people/</a><p data-notion-block-id=\\"1f0e548d-8a8e-8055-8a31-df540435fcef\\">2FA(2\ub2e8\uacc4 \uc778\uc99d)\uc774 \uc5b4\ub5a4 \ubb38\uc81c\uac00 \uc788\uace0, Passkey\uac00 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\uace0 \uc5b4\ub5a4 \ubb38\uc81c\uc0c1\ud669\uc744 \ud574\uacb0\ud558\ub824\uace0 \ub098\uc628 \uae30\uc220\uc778\uc9c0 \ube44\uac1c\ubc1c\uc790\ub3c4 \uc54c \uc218 \uc788\ub3c4\ub85d \uc4f4 \uae00\uc785\ub2c8\ub2e4. \ub9cc\uc57d web\uc5d0\uc11c\uc758 passkey\uc640 \uad00\ub828\ub41c \ub354 \uc790\uc138\ud55c \ud788\uc2a4\ud1a0\ub9ac\ub098 \uc791\ub3d9 \uc6d0\ub9ac\ub97c \uc54c\uace0 \uc2f6\ub2e4\uba74, <a href=\\"https://ones-to-watch.ethansup.net/news/post/16be548d-8a8e-8042-ae4b-ff077a1a1d1f#16be548d-8a8e-805f-b515-e4b56c976f4a\\">WebAuthn \uc5ec\ud589 \uae00</a>\uc744 \ucc38\uace0\ud558\uc138\uc694!</p><h2 data-notion-block-id=\\"1f0e548d-8a8e-8075-9fd6-f299ff568793\\" id=\\"1f0e548d-8a8e-8075-9fd6-f299ff568793\\">RSC\ub294 \uc6b0\ub9ac\uc5d0\uac8c \uc120\ud0dd\uad8c\uc744 \uc900\ub2e4.</h2><a href=\\"https://saewitz.com/server-components-give-you-optionality\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://saewitz.com/server-components-give-you-optionality</a><p data-notion-block-id=\\"1f0e548d-8a8e-8038-9306-de11f7f30106\\">CSR\uacfc SSR\uc744 \uc18c\uac1c\ud558\uba74\uc11c, \uadf8 \uc0ac\uc774\uc5d0\uc11c RSC\uac00 \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\ub294\uc9c0, \uae30\uc874 \uc5ed\ud560\uacfc\ub294 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uac04\ub2e8\ud558\uac8c fetch\ub9cc\uc744 \uc0ac\uc6a9\ud588\uc9c0\ub9cc,<a href=\\"https://www.trevorlasn.com/blog/fetching-data-for-complex-next-and-react-apps\\"> \ud070 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \ub2e8\uc5d0\uc11c\ub294 \uc544\ud0a4\ud14d\uccd0\uc758 \uc77c\ubd80\ub85c\uc11c \uc0ac\uc6a9</a>\ud560 \uc218 \uc788\uc73c\ubbc0\ub85c, \uc798 \uc0dd\uac01\ud574\ubd10\uc57c\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f0e548d-8a8e-8072-923f-f03a3306f2cc\\" id=\\"1f0e548d-8a8e-8072-923f-f03a3306f2cc\\">Promise\uc758 \ub0b4\ubd80</h2><a href=\\"https://www.deepintodev.com/blog/how-promises-work-in-javascript\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.deepintodev.com/blog/how-promises-work-in-javascript</a><p data-notion-block-id=\\"1f0e548d-8a8e-802b-a775-d260f8ccb5bb\\">\ubcf5\uc7a1\ud55c Promise(\uc640 console.log)\ub85c\uc9c1\uc744 \uc0b4\ud3b4\ubcf4\uba74\uc11c Promise\uac00 \uc5b4\ub5bb\uac8c \ud758\ub7ec\uac00\ub294\uc9c0 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub354 interactive\ud55c \uae00\uc744 \ubcf4\ub824\uba74, <a href=\\"https://www.lydiahallie.com/blog/promise-execution\\">Visualized Promise in event loop</a>\uae00\uc744 \ucc38\uace0\ud558\uc138\uc694!</p><h2 data-notion-block-id=\\"1f0e548d-8a8e-800c-9b21-e7015515d0ad\\" id=\\"1f0e548d-8a8e-800c-9b21-e7015515d0ad\\">JS\uc640 \ubb38\uc790\uc5f4</h2><a href=\\"https://2ality.com/2025/04/stringification-javascript.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2ality.com/2025/04/stringification-javascript.html</a><p data-notion-block-id=\\"1f0e548d-8a8e-80ec-a16b-edb1ce7ba67e\\">JavaScript\uc758 \uc5ec\ub7ec \uac12\uc744 \ubb38\uc790\uc5f4\ub85c \ubc14\uafb8\ub294 \ubc29\uc2dd\uc5d0 \ub300\ud574 \ube44\uad50\ud558\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f0e548d-8a8e-8073-824b-fe3c779a980a\\" id=\\"1f0e548d-8a8e-8073-824b-fe3c779a980a\\">Node.js\ub294 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uac00?</h2><a href=\\"https://www.deepintodev.com/blog/how-nodejs-works-behind-the-scenes\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.deepintodev.com/blog/how-nodejs-works-behind-the-scenes</a><p data-notion-block-id=\\"1f0e548d-8a8e-80ed-a6fa-df0a57375ff7\\">Node.js\uac00 I/O\ubd80\ud130 \uc2dc\uc791\ud574\uc11c \uc6f9 \ube0c\ub77c\uc6b0\uc800\uc758 \ub3d9\uc791\ubc29\uc2dd\uacfc \ube44\uad50\ud574\uc11c Node.js\uc758 \uc791\ub3d9\ubc29\uc2dd\uc744 \uc790\uc138\ud558\uac8c \uc54c\ub824\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://www.youtube.com/watch?v=cCOL7MC4Pl0\\">\ube0c\ub77c\uc6b0\uc800\uc758 Event loop</a>\uc640 \ube44\uad50\ud574\uc11c \ubcf4\ub294 \uac83\uc774 \ub354 \uc88b\uc2b5\ub2c8\ub2e4 :)</p><h2 data-notion-block-id=\\"1f0e548d-8a8e-8004-8407-c4c864858933\\" id=\\"1f0e548d-8a8e-8004-8407-c4c864858933\\">Image Map \uc0b4\ud3b4\ubcf4\uae30</h2><a href=\\"https://css-tricks.com/revisiting-image-maps/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://css-tricks.com/revisiting-image-maps/</a><p data-notion-block-id=\\"1f0e548d-8a8e-80b5-901b-d575608b5fdf\\">image \uae30\ubc18 <code>&#x3C;map></code>\ud0dc\uadf8\ub97c \uc0ac\uc6a9\ud560 \ub54c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294\uc9c0, \uc8fc\uc758\ud560 \uc810\uc740 \ubb34\uc5c7\uc778\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f0e548d-8a8e-80a4-b156-dfa38799fe2f\\" id=\\"1f0e548d-8a8e-80a4-b156-dfa38799fe2f\\">CSS polyfill(\uac00\uc0c1\uc73c\ub85c) \uad6c\ud604\ud574\ubcf4\uae30</h2><a href=\\"https://www.bram.us/2025/05/04/css-parser-extensions-pitch/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.bram.us/2025/05/04/css-parser-extensions-pitch/</a><p data-notion-block-id=\\"1f0e548d-8a8e-8036-b212-fa4daa508a77\\">CSS Parser extension\uc774\ub77c\ub294 \uc544\uc774\ub514\uc5b4\ub97c \ud1b5\ud574 CSS polyfill\uc744 \uad6c\ud604\ud558\uc790\ub294 \uc544\uc774\ub514\uc5b4 \ucc28\uc6d0\uc5d0\uc11c\uc758 \uae00\uc785\ub2c8\ub2e4. \ud765\ubbf8\ub86d\uac8c \ubcf4\uc2e0 \ubd84\uc740 \uae00\uc5d0\uc11c \uc18c\uac1c\ud55c \uad00\ub828 \uae00\uc778 <a href=\\"https://philipwalton.com/articles/the-dark-side-of-polyfilling-css/\\">CSS polyfill\uc740 \uc5b4\ub835\ub2e4</a>\ub3c4 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f0e548d-8a8e-8054-992b-d209f1f6c0ed\\" id=\\"1f0e548d-8a8e-8054-992b-d209f1f6c0ed\\">\uc811\uadfc\uc131 \uc88b\uc740 \ud3fc\uc744 \uc704\ud55c \ud301</h2><a href=\\"https://afixt.com/accessible-forms-tips-and-techniques/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://afixt.com/accessible-forms-tips-and-techniques/</a><p data-notion-block-id=\\"1f0e548d-8a8e-8069-bd00-ede7b6feacac\\">form\uc744 \ub9cc\ub4e4 \ub54c \uac04\ub2e8\ud558\uac8c \uc801\uc6a9\ud558\uae30 \uc88b\uc740 \uc5ec\ub7ec\uac00\uc9c0 \uc811\uadfc\uc131 \ud301\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"1f0e548d-8a8e-8031-9998-d7912a5275fb\\" id=\\"1f0e548d-8a8e-8031-9998-d7912a5275fb\\">\ub2e4\ud06c\ubaa8\ub4dc toggle \ubc84\ud2bc \uad6c\ud604\ud558\uae30</h2><a href=\\"https://sergiodxa.com/tutorials/add-a-color-scheme-toggle-in-react-router\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://sergiodxa.com/tutorials/add-a-color-scheme-toggle-in-react-router</a><p data-notion-block-id=\\"1f0e548d-8a8e-80ac-9ac0-e5d7f7900108\\">React Router\uc5d0\uc11c \uc11c\ubc84\uc640 \ud568\uaed8 \ub2e4\ud06c\ubaa8\ub4dc \ubc84\ud2bc\uc744 \uad6c\ud604\ud558\ub294 \uae00\uc774\uc9c0\ub9cc, \uc57d\uac04\ub9cc \ubc14\uafb8\uba74 \ub2e4\ub978 \ud504\ub808\uc784\uc6cc\ud06c\uc5d0\ub3c4 \uc801\uc6a9\ud560 \uc218 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"1eee548d-8a8e-80cc-9dfa-e2da404fc79c\\" id=\\"1eee548d-8a8e-80cc-9dfa-e2da404fc79c\\">\uc81c\ud488\uc5d0 \uc88b\uc740 \uc811\uadfc\uc131\uc744 \uc704\ud574 \uc6b0\ub9ac\uac00 \ud574\ubcfc \uc218 \uc788\ub294 \uac83\ub4e4</h2><a href=\\"https://www.smashingmagazine.com/2025/04/fostering-accessibility-culture/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2025/04/fostering-accessibility-culture/</a><p data-notion-block-id=\\"1f0e548d-8a8e-806f-96b9-f1d61efb7c89\\">\uc811\uadfc\uc131\uc744 \uc704\ud574 \uac1c\ubc1c\uc790 \ucc28\uc6d0\uc774 \uc544\ub2c8\ub77c, \ubb38\ud654\ucc28\uc6d0\uc5d0\uc11c, \ud639\uc740 \ud504\ub85c\uc138\uc2a4 \ucc28\uc6d0\uc5d0\uc11c \uc0dd\uac01\ud574\ubcfc\ub9cc\ud55c \uac83\ub4e4\uc744 \uc81c\uc2dc\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f0e548d-8a8e-80a6-a535-c17635f1f277\\" id=\\"1f0e548d-8a8e-80a6-a535-c17635f1f277\\">React \ubc16\uc5d0\uc11c\uc758 RSC</h2><a href=\\"https://overreacted.io/functional-html/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://overreacted.io/functional-html/</a><p data-notion-block-id=\\"1f0e548d-8a8e-80f3-86a1-fb23a5174b66\\">HTML\uc744 Server Components\ub85c \ub9cc\ub4e4\uba74\uc11c RSC\uac00 \uc8fc\ub294 \uc7a5\uc810\uc744 \ub418\uc0c8\uae38 \uc218 \uc788\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://overreacted.io/rsc-for-astro-developers/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://overreacted.io/rsc-for-astro-developers/</a><p data-notion-block-id=\\"1f0e548d-8a8e-80ea-b60e-c45d50705e3c\\">Astro\uc758 Island Arcitecture\uacfc React Server Component\uacfc \ube44\uad50\ud574\ubcf4\uba74\uc11c \ub2ee\uc740 \uc810\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://romanliutikov.com/blog/towards-react-server-components-in-clojure-part-1\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://romanliutikov.com/blog/towards-react-server-components-in-clojure-part-1</a><p data-notion-block-id=\\"1f0e548d-8a8e-80bf-b00e-c933b1f2c7cd\\">Clojure\uc5d0\uc11c RSC\ub97c \uc0ac\uc6a9\ud558\uae30 \uc704\ud574\uc11c RSC \ub370\uc774\ud130 \uc9c1\ub82c\ud654\ub97c Clojure\ub85c \uc62e\uae30\ub294 \uacfc\uc815\uc744 \uc9c4\ud589\ud588\uace0, \ub2e4\ub978 \uacfc\uc815\uc744 \uc9c4\ud589\ud560 \uc608\uc815\uc784\uc744 \ubc1d\ud788\ub294 \uae00\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"1f0e548d-8a8e-8098-aaee-cd8c920ba792\\">\uc704 \uc138 \uae00\uc740 RSC\ub97c Next.js \ubc14\uae65\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4(\uc804\uc790\ub294 \uac1c\ub150\ub9cc \ube44\uad50\ud558\ub294 \uae00\uc774\uc9c0\ub9cc). Server Component\uc758 \uac1c\ub150\uacfc \uc9c1\ub82c\ud654 \ubc29\uc2dd\uc740 \ub110\ub9ac \ud37c\uc9c8 \uc218\ub3c4 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"1ebe548d-8a8e-80a2-82d5-fde2bc264fe9\\" id=\\"1ebe548d-8a8e-80a2-82d5-fde2bc264fe9\\">\uc8fc\ubaa9\ud560\ub9cc\ud55c \uce5c\uad6c\ub4e4</h2><a href=\\"https://antfu.me/posts/categorize-deps\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://antfu.me/posts/categorize-deps</a><p data-notion-block-id=\\"1f0e548d-8a8e-8027-b5cb-c4e5b61d2e0e\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/14ae548d-8a8e-8059-b8c9-cc040779dd9f#150e548d-8a8e-807a-9538-f2883fc9c306\\">\uc5b4\ub5a4 \uacbd\uc6b0\uc5d0 devDependencies\ub97c \uc0ac\uc6a9\ud574\uc57c \ud560\uae4c</a>\ub294 \uc784\uc758\ub85c \ud300\ub9c8\ub2e4 \uc5b4\ub5a4 \uc804\ub7b5\uc744 \uc0ac\uc6a9\ud558\uba74 \uc88b\uc744\uc9c0 \uc5ec\ub7ec\uac00\uc9c0\uc758 \uc811\uadfc \ubc29\uc2dd\uc744 \uc18c\uac1c\ud588\ub2e4\uba74, \uc774 \uae00\uc740 pnpm catalog\uc640 \uc790\uc2e0\uc774 \ub9cc\ub4e0 \ud328\ud0a4\uc9c0\uc640 \uc775\uc2a4\ud150\uc158\uc744 \ubc14\ud0d5\uc73c\ub85c pnpm catalog\ub97c \uc798 \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud2b9\ud788 <a href=\\"https://github.com/antfu/node-modules-inspector\\">node module inspector</a>\uc758 \uacbd\uc6b0\uc5d0\ub294 deprecated\ub41c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc798 \uc9da\uc5b4\uc8fc\uae30 \ub54c\ubb38\uc5d0 \uc0c8\ub85c\uc6b4 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0 \uc811\uadfc\ud560 \uacbd\uc6b0 \uc774 \ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud558\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://sst.dev/blog/frontends-are-hard\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://sst.dev/blog/frontends-are-hard</a><p data-notion-block-id=\\"1f0e548d-8a8e-80b6-949a-c48d6339d4ba\\">\ud504\ub860\ud2b8\uc5d4\ub4dc\uc758 \uc778\ud504\ub77c\uac00 \uc5b4\ub824\uc6cc\uc9c4 \uc774\uc720\ub97c \ubd84\uc11d\ud558\uba74\uc11c SST\ub294 \uc5b4\ub5bb\uac8c \ud504\ub860\ud2b8\uc5d4\ub4dc \uc778\ud504\ub77c\uc758 \ubcf5\uc7a1\ud568\uc744 \ud480\uc5b4\ub0c8\ub294\uc9c0\uc5d0 \ub300\ud55c \uae00\uc785\ub2c8\ub2e4. SST\uc5d0 \uad00\uc2ec\uc774 \uc5c6\ub354\ub77c\ub3c4, \ud504\ub860\ud2b8\uc5d4\ub4dc \uc778\ud504\ub77c\uac00 \ubcf5\uc7a1\ud574\uc9c4 \uc774\uc720\uc5d0 \ub300\ud574\uc11c\ub294 \uaf2d \ubcf4\uc168\uc73c\uba74 \uc88b\uaca0\ub124\uc694.</p><a href=\\"https://gsap.com/blog/3-13/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gsap.com/blog/3-13/</a><p data-notion-block-id=\\"1ede548d-8a8e-805a-86fb-fbbeafdad56f\\">\uc560\ub2c8\uba54\uc774\uc158\uc744 \ub2e4\uc591\ud558\uac8c \uad6c\ud604\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 GSAP\uc758 \ud50c\ub7ec\uadf8\uc778\ub4e4\uc774 \ubb34\ub8cc\uac00 \ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. \uc560\ub2c8\uba54\uc774\uc158\uc744 \ub354 \ub2e4\uc591\ud558\uace0 \uc27d\uac8c \ub9cc\ub4e4 \uc218 \uc788\uaca0\ub124\uc694.</p><a href=\\"https://unhead.unjs.io/v2\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://unhead.unjs.io/v2</a><p data-notion-block-id=\\"1ede548d-8a8e-80ca-a1e3-d071e314c5b2\\"><code>&#x3C;head></code>\ud0dc\uadf8\ub97c \uc218\uc815\ud560 \uc218 \uc788\ub294 unhead \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 2\ubc84\uc804\uc5d0 \ub3c4\ub2ec\ud588\uc2b5\ub2c8\ub2e4. \ub9ce\uc774 \uc0ac\uc6a9\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 \ubaa8\ub450 \uc9c0\uc6d0\ud558\ubbc0\ub85c, \ub9cc\uc57d \uc9c0\uae08 \uc0ac\uc6a9\ud558\uace0 \uacc4\uc2e0 head\ub97c \uc218\uc815\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 depreacted\ub418\uc5c8\ub2e4\uba74 \ud55c\ubc88 \uace0\ubbfc\ud574\ubcfc\ub9cc \ud569\ub2c8\ub2e4.</p><a href=\\"https://github.com/ixahmedxi/unverceled-nextjs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/ixahmedxi/unverceled-nextjs</a><p data-notion-block-id=\\"1f0e548d-8a8e-80d4-9fa9-c61c2daa7cb6\\">next.js\uc758 \uae30\ubcf8 \ubc30\ud3ec \ubc29\uc2dd\uc778 vercel\uc744 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uace0 cloudflare\uc5d0 \ubc30\ud3ec\ud558\ub294 \ubc29\uc2dd\uc744 opennext\ub97c \ud1b5\ud574 \ud560 \uc218 \uc788\ub294 \ud15c\ud50c\ub9bf\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.youtube.com/watch?v=t9t-VXwIc4I\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=t9t-VXwIc4I</a><p data-notion-block-id=\\"1f2e548d-8a8e-8089-87a4-cf2825c74ae9\\">React Native\uc5d0\uc11c ThreeJS, WebGPU\u2026 React Native \uc548 \uc0dd\ud0dc\uacc4\uc758 GPU\ub97c \uc0ac\uc6a9\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc5d0 \ub300\ud55c \uc5ec\ub7ec\uac00\uc9c0 \uc18c\uac1c \uc601\uc0c1\uc785\ub2c8\ub2e4.</p><a href=\\"https://mantine.dev/changelog/8-0-0/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://mantine.dev/changelog/8-0-0/</a><p data-notion-block-id=\\"1ede548d-8a8e-804d-8770-dc65c8a80dec\\">\ub9ac\uc561\ud2b8 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 Mantine 8\ubc84\uc804\uc774 \ub4f1\uc7a5\ud588\uc2b5\ub2c8\ub2e4.</p>"}')}}]);